		line(name + " types", [priv.type, pub.type, priv.asymmetricKeyType, pub.asymmetricKeyType, priv.asymmetricKeyDetails, pub.asymmetricKeyDetails]);
		line(name + " seed", hex(priv.export({ format: "raw-seed" })));
